select * from jsonb_to_recordset('[{"id": "689f1353-4282-5515-9773-bb6259838a84", "status": "repair_and_verified", "solution": "Assuming independent shots, the probability of scoring all three is 0.3 × 0.3 × 0.3 = 0.027.", "expected_key": "A", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {"image": "https://math.portal.ghoneem.com/exams/est-march-2026/q06.png", "stem": "Mohammad scores each penalty shot with probability 0.3. Assuming three shots are independent, what is the probability he scores all three?", "choices": [{"key": "A", "text": "0.027"}, {"key": "B", "text": "0.343"}, {"key": "C", "text": "0.540"}, {"key": "D", "text": "0.90"}]}, "q_digest": "26c10a73e33c0ee4745c0343872dbb84", "key_digest": "83518b71e880e51fdc6416c6d7eebe9a", "fingerprint": "2eee44ec03879d10224dc4809be9db35"}, {"id": "6943cd8b-d4ab-57d3-9fb9-78e993d22f5a", "status": "mathematically_verified", "solution": "Complete squares: (x-3)^2+(y-2)^2=4, center(3,2), radius 2. Distance to x=5 is 2, making it tangent. The other listed lines have center distances 4/sqrt(10),1/sqrt(2),1, all less than 2.", "expected_key": "D", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {}, "q_digest": "0d73afa95813b0624083a67c313a0e28", "key_digest": "81cf99e9ca1b124b963aa0b1ecf67eb6", "fingerprint": "016b356810636615759822d7a5526ef2"}, {"id": "6a1f631a-6320-5688-8fae-2f04082dba4b", "status": "repair_and_verified", "solution": "The fitted increase is (19 − 17.4)/(2015 − 2010) = 0.32 per year, rounding to 0.3.", "expected_key": "C", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {"image": "http