ginal source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {"image": "https://math.portal.ghoneem.com/exams/est-banks-2026/figures/dap-062-1.png"}, "q_digest": "6f82f360e821a55f8b63d70d2cca3831", "key_digest": "079a2739f970f6d74db48c0222e97a9e", "fingerprint": "0f699c54c61fc31e970ee4dde67d43aa"}, {"id": "756766cb-80b1-5643-91a9-dee54bc64f4b", "status": "repair_and_verified", "solution": "The median is nearer Q1 and the upper half and right whisker are longer, indicating positive (right) skew.", "expected_key": "D", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {"image": "https://math.portal.ghoneem.com/exams/est-banks-2026/figures/dap-073-1.png"}, "q_digest": "ca709caec53194f4d210b774cf9b5c49", "key_digest": "eb00fc0097534a2db2f9a7104da097f1", "fingerprint": "bfdcfcb4a7323c9753e1d7df8039cf6b"}, {"id": "7604eeb0-6c7c-5e79-b50a-b9ba823029ac", "status": "repair_and_verified", "solution": "Substitute x = −1 and y = −2: |2(−1) − 3(−2)| + 4(−2) = |4| − 8 = −4.", "expected_key": "B", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {"image": "https://math.portal.ghoneem.com/exams/est-march-2026/q41.png"}, "q_digest": "d2ef4cc744fa5c31ce01370f780983f5", "key_digest": "01c40405408b35f3d4f87aefd7a0b0bc", "fingerprint": "2d07915c73879948fd804ae2fac9be35"}, {"id": "78f51057-82aa-5f3b-bd58-79d45b28510e", "status": "mathematically_verified", "solution": "1-2x-x^2=2-(x+1)^2, so maximum is 2 and is attained at x=-1.", "expected_key": "B", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {}, "q_digest": "c519a09d0ff675809b8057c80fe30755", "key_digest": "277c6ce5da7bfa8024a99a6a18016e54", "fingerprint": "4291a0b87b2ba29886e74e1cd6a42522"}, {"id": "7c5e9a6d-3c05-5f6d-806a-c23a276eb018", "status": "repair_and_verified", "solution": "f(1) = −3(1 + 4) − 4(1)² = −19. g(1) = 2 − 1 + 1 = 2. The quotient is −19/2 = −9.5.", "expected_key": "A", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {"image": "https://math.portal.ghoneem.com/exams/est-march-2026/q09.png"}, "q_digest": "68d27b5598e0b6f694374507b92a06b9", "key_digest": "651a4e07d54b7e5a6f4764c01de9612a", "fingerprint": "17618f1204609ba92ca48d5ea69957ac"}, {"id": "7d36801e-f7f9-5bb5-836c-d3fa0d7de448", "status": "repair_and_verified", "solution": "The two remaining slices total 100 − 39 − 26 − 15 = 20%. Vaccinations receives 3/5 of this, or 12%.", "expected_key": "B", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {"image": "https://math.portal.ghoneem.com/exams/est-banks-2026/figures/dap-047-1.png"}, "q_digest": "a6219b4e5b10b19a3195170456afa6fd", "key_digest": "2c37a3107a227f2eb6b06c02890d981c", "fingerprint": "5bdd1b221df71e5dfa85807773f6a1e1"}, {"id": "7d81f146-e068-5834-bf6e-72c2f910578a", "status": "repair_and_verified", "solution": "3x − 7 = 20 gives x = 9. Therefore 2x = 18.", "expected_key": "D", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {"image": "https://math.portal.ghoneem.com/exams/est-march-2026/q33.png"}, "q_digest": "85ac778026d8ba72a0eb89db94dd61c9", "key_digest": "9af9598ab0930261367558e4e42dcf6d", "fingerprint": "d02abd356d773ecd744e3eb0a88e865e"}, {"id": "7e7c0616-6587-5cce-b21e-2a28c044cbb0", "status": "repair_and_verified", "solution": "The known color percentages sum to 20 + 33 + 10 + 14 = 77%. Silver accounts for the remaining 23%. Red or silver accounts for 20% + 23% = 43%, so the probability is 0.43.", "expected_key": "D", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {"explanation": "The known color percentages sum to 20 + 33 + 10 + 14 = 77%. Silver accounts for the remaining 23%. Red or silver accounts for 20% + 23% = 43%, so the probability is 0.43."}, "q_digest": "648d0992384eeb09505b1e9635c0b9c2", "key_digest": "2382c74243ca4fed6628be3054476238", "fingerprint": "356faf09ccf3d9bce220a4fff7610ed3"}, {"id": "7f1fa1bf-1d47-5439-b883-62e7e66cb8f3", "status": "mathematically_verified", "solution": "BH is the hypotenuse. cos(H)=GH/BH=0.5, hence GH=5.", "expected_key": "C", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {}, "q_digest": "af393b774a2cbccdd0108da6b57b8e73", "key_digest": "8e9fb63fb016f471897265451299417d", "fingerprint": "19e061ec42620b52614e28ca4a6e4556"}, {"id": "800afc05-f12f-5c20-976b-c41e0c814101", "status": "mathematically_verified", "solution": "ALGEBRA has 7 letters with A repeated twice, so 7!/2!=2520.", "expected_key": "D", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {}, "q_digest": "8528f0f4500cfd2d7dd54a38c85b266c", "key_digest": "ff171dd441ac9cad57e42a65bcd9a1e9", "fingerprint": "367dd28ac367d7c9e281439293f64f99"}, {"id": "80464b7b-e86d-5f4f-9558-ff6a176909f1", "status": "repair_and_verified", "solution": "Rewrite as 2x^2-4x+10=0. Product c/a=5. Roots are complex; do not describe them as real solutions.", "expected_key": "B", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {"stem": "What is the product of the two complex roots, counted with multiplicity, of 2x² − 4x = −10?", "choices": [{"key": "A", "text": "−5"}, {"key": "B", "text": "5"}, {"key": "C", "text": "10"}, {"key": "D", "text": "2"}]}, "q_digest": "51e5c9f0d649c76320b23d6ee91f4fd0", "key_digest": "a28d5579af8fae5102a38213eb5b856f", "fingerprint": "30504d13be7181be53df6010251084ab"}, {"id": "8105e65e-218d-5711-9e17-2fc75f65ed5a", "status": "repair_and_verified", "solution": "The line inside the box marks the median at 10.", "expected_key": "B", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {"image": "https://math.portal.ghoneem.com/exams/est-banks-2026/figures/dap-005-1.png"}, "q_digest": "2ec3907bd2522bbde7d02b1f8408f532", "key_digest": "2b67ccb9070a0cdebfdc1e5a5660f481", "fingerprint": "8a56b1afda63b59fe1f07b8b28455e3a"}, {"id": "86ddf58a-3409-57ac-a8ba-77c3a0a8841f", "status": "repair_and_verified", "solution": "The slope from (2,5) to (7,15) is 10/5 = 2, so y = 2x + 1. At x = 5, a = 11. Therefore 2a = 22.", "expected_key": "D", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {"image": "https://math.portal.ghoneem.com/exams/est-march-2026/q26.png"}, "q_digest": "771642d5a90c6ef4033d9d066ffced32", "key_digest": "cec79f2612125e3ad9a349f595564f2e", "fingerprint": "b3a91ae826e494ca2e0cf80bfa88a036"}, {"id": "8748477f-6181-523d-ac49-eb7baee033d4", "status": "mathematically_verified", "solution": "20*1.07*0.92=19.688. Use successive multipliers rather than adding rates.", "expected_key": "B", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {}, "q_digest": "ae7264385007ce5e25620bcc8d03635f", "key_digest": "737e1e0d7855de82915f0c6f20d501cf", "fingerprint": "1378f41e762f6160a18203c09548aa9d"}, {"id": "88e08477-5982-56a8-8b03-598034c5a43e", "status": "repair_and_verified", "solution": "Combining cubic terms gives (3a + 1)x³ + 4bx² + x. The cubic coefficient must be zero: 3a + 1 = 0, so a = −1/3. For the result actually to be quadratic, b must also be nonzero.", "expected_key": "B", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {"image": "https://math.portal.ghoneem.com/exams/est-march-2026/q24.png", "stem": "Let f(x) = 3ax³ + 4bx² + x + x³, where a and b are real numbers and b ≠ 0. What value of a makes f a quadratic polynomial?", "choices": [{"key": "A", "text": "−1"}, {"key": "B", "text": "−1/3"}, {"key": "C", "text": "0"}, {"key": "D", "text": "3"}]}, "q_digest": "ca378acf6d77056d4b9931c8f054699a", "key_digest": "0102f661451f21a46a99e19e73b9b225", "fingerprint": "794f488e8074bb2c501c49d25b1d2047"}, {"id": "896f5c85-41c2-5049-bffe-b3526d450f80", "status": "repair_and_verified", "solution": "In right triangle ADC, DC = √(15² − 9²) = 12 cm. In right triangle BDC, BD = √(20² − 12²) = 16 cm. Hence AB = 9 + 16 = 25 cm and the area is (1/2)(25)(12) = 150 cm².", "expected_key": "C", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {"image": "https://math.portal.ghoneem.com/exams/est-march-2026/q47.png"}, "q_digest": "8d029979be874d918d83b3337d161347", "key_digest": "ded73d91c744f59f3d049264cebb9659", "fingerprint": "e501cb4108bdec81d8db2fec12c065bf"}, {"id": "8ba22672-67e8-5dba-a212-42c07a186b6b", "status": "repair_and_verified", "solution": "The discriminant is b² − 4ac = (−3)² − 4(3)(1) = 9 − 12 = −3.", "expected_key": "B", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {"image": "https://math.portal.ghoneem.com/exams/est-march-2026/q37.png"}, "q_digest": "1593954a501e398eb835ea7577b3ec2d", "key_digest": "8294aec54d19bd03151f4fd46281c27e", "fingerprint": "926ddec96012b35b30fcdfe7bccb7a7b"}, {"id": "8bea6a7e-13f6-58bb-9e02-f59bf0a3c1d1", "status": "mathematically_verified", "solution": "Scores 40,55,75,80,95 have frequencies 2,4,6,7,1, totaling 20. Positions 10 and 11 fall in the 75 group, hence median 75.", "expected_key": "75", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {}, "q_digest": "10ce7119fdc1a906f67d4b84f376e86b", "key_digest": "0f93758ee7d1e0a9ffb08cfbd8de9eef", "fingerprint": "af6398c5679ce331ef6b15ee5a03039c"}, {"id": "8f5cacd9-31bb-57ce-bf65-ba4ef5cdc529", "status": "mathematically_verified", "solution": "9^(2x-1)=3^8 implies 4x-2=8, x=5/2, so 2x-5=0.", "expected_key": "B", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {}, "q_digest": "aa02781a476cff9fbed7f99aa7deea30", "key_digest": "0e78e7c376547738de212dc2470bdd47", "fingerprint": "048db606f259398e80ebf816cabe5e09"}, {"id": "92548ac0-8965-5cbb-aa65-81978147112f", "status": "repair_and_verified", "solution": "For 14 values the median averages positions 7 and 8: (24 + 36)/2 = 30 minutes.", "expected_key": "C", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {"image": "https://math.portal.ghoneem.com/exams/est-banks-2026/figures/dap-074-1.png"}, "q_digest": "23b964a0eecc89fa82f41029755043cc", "key_digest": "315dd622cd4e5372abc51183a967fad4", "fingerprint": "274251bdb5468ac640a679a2a3fb9d84"}, {"id": "93628e9e-dbd9-5dde-af49-b12de63a7652", "status": "repair_and_verified", "solution": "3x − 4 ≤ 1 gives x ≤ 5/3. The greatest positive integer satisfying this is 1.", "expected_key": "A", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {"image": "https://math.portal.ghoneem.com/exams/est-march-2026/q30.png"}, "q_digest": "9f4adf96da27fadf5f297e11fca7ea30", "key_digest": "089c9f8d4067e0af249119e2bfe0c0b5", "fingerprint": "9fd152314793075eea643b4c7d4ec1aa"}, {"id": "944c6cf6-bc98-5a4b-8ffc-037b5eebf8ce", "status": "mathematically_verified", "solution": "205*(172+100)+12*3994=55760+47928=103688.", "expected_key": "A", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {}, "q_digest": "907231c5754a494092d6dcf048efa5a2", "key_digest": "6f11a63c4a6844cd90e973e495d6f801", "fingerprint": "2fb23f39e2466defef1386a5da6c5c2a"}, {"id": "95c19228-f767-52bd-b954-08d0c1e2b703", "status": "mathematically_verified", "solution": "Complete the square: 2[x^2-6x]+8=2[(x-3)^2-9]+8.", "expected_key": "B", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {}, "q_digest": "2b5399adbb75b7d148f8b35fe8e811f9", "key_digest": "ae5ad079458db10b49e076579ee58cf0", "fingerprint": "b9ffa603fbbe7253110603257d549714"}, {"id": "97e14662-6707-58fb-84f6-6eeedb723ee1", "status": "repair_and_verified", "solution": "Simple interest = principal × annual rate × years = 4,500 × 0.02 × 2 = USD 180.", "expected_key": "B", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {"image": "https://math.portal.ghoneem.com/exams/est-march-2026/q14.png"}, "q_digest": "26df030861acd52f0247d28bb029968f", "key_digest": "c1158cf08db3909944a71bc9abcec551", "fingerprint": "7f33a4b02866a5a3ba5b59acfdf2ab9f"}, {"id": "9b259467-cfc1-5370-8a15-47e33d036843", "status": "repair_and_verified", "solution": "(f + g)(x) = (2x + 1) + (−3x + 1) = −x + 2. At x = 1, the value is 1.", "expected_key": "A", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {"image": "https://math.portal.ghoneem.com/exams/est-march-2026/q32.png"}, "q_digest": "89eac7cf95ae966b10b117d36655d034", "key_digest": "dbfafede40371e048b215a40b05e9f45", "fingerprint": "3a7c78fcedf7d794ba7f4d8540d5ab4c"}, {"id": "9c3ebc18-9650-5d54-a6c9-5fd87fe4ca0f", "status": "mathematically_verified", "solution": "For consecutive vertices A,B,C,D, D=A+C-B=(-1,-2). Opposite sides have equal vectors.", "expected_key": "C", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {}, "q_digest": "d47f2314b1063140b64a82f97435a991", "key_digest": "34c9e6510e740fc1a8a7de30c4ff1aaa", "fingerprint": "7b888a62c98f96b0588e02bc233a2905"}, {"id": "9ccb2449-d490-5b31-9fb6-2f61daa9c95d", "status": "repair_and_verified", "solution": "Substitute y = 6 into x + 5y = 33 to get x = 3. Then ax + 3y = 24 becomes 3a + 18 = 24, so a = 2.", "expected_key": "C", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {"image": "https://math.portal.ghoneem.com/exams/est-march-2026/q34.png"}, "q_digest": "28b8a00f7344042fbec85f5ab4813f13", "key_digest": "e58b8c1f3dac97bf9ed8853cb41202ee", "fingerprint": "b6234ede9a41c5fad1d4daee1a456fd7"}, {"id": "9d3e6732-cc91-5499-aaa2-48c89012c2c7", "status": "repair_and_verified", "solution": "There are 101 + 60 = 161 boys out of 101 + 60 + 125 + 34 = 320 students. Probability = 161/320 = 0.503125, approximately 0.503.", "expected_key": "C", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {"image": "https://math.portal.ghoneem.com/exams/est-march-2026/q10.png"}, "q_digest": "2df5ac372fc109d428c7f7b20e9d7591", "key_digest": "19104d8876ae4d65a9390599bfad587d", "fingerprint": "2eb0e1c8723767f80c482cc36581e9e8"}, {"id": "9f06088e-21c4-5ab3-a3f7-46fe8b53c5fc", "status": "repair_and_verified", "solution": "Slope = (4 − 3)/(1 − (−9)) = 1/10. Using (1,4), the intercept is 4 − 0.1 = 3.9. Therefore y = 0.1x + 3.9.", "expected_key": "C", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {"image": "https://math.portal.ghoneem.com/exams/est-march-2026/q08.png"}, "q_digest": "bfdec3a2b933a71cb00f71ae2ae9ec3d", "key_digest": "edb1c1fe62cdbdaf809ee1c10ee7175a", "fingerprint": "a9e76724e51bf7a895aa5b5f95c2846a"}, {"id": "a0aaad46-4c23-5cf7-86b9-ff68e0aaa2e9", "status": "repair_and_verified", "solution": "The sum is 7k + (k + 10) + (3k + 2) + (4k − 4) = 15k + 8. An average of 5 for four numbers means a sum of 20, so 15k = 12 and k = 0.8.", "expected_key": "B", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {"image": "https://math.portal.ghoneem.com/exams/est-march-2026/q15.png"}, "q_digest": "2ae0e134c4b1ad0549fa956a0d3c19d7", "key_digest": "0ecc4989df8d4d3efca4c7e43815982e", "fingerprint": "39129c79d28c8cf03ba006c5fb6d9d89"}, {"id": "a2ea44d8-a65c-5e19-a9f4-34d4198b29b7", "status": "mathematically_verified", "solution": "Set t=3: (2x-4)/3-(x+1)/6=4. Multiply by 6 to get 4x-8-x-1=24;3x=33,x=11. Substitution gives 6-2=4.", "expected_key": "C", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {}, "q_digest": "7f4150195da72ae4dd46afb55f69d582", "key_digest": "b4d6d6f48c524eecb76def566b1fa5e4", "fingerprint": "369ba2be2e12ea172c8f0bb605f1bac6"}, {"id": "a4b201d7-e3ff-517e-b686-56d08c186e58", "status": "mathematically_verified", "solution": "The upper triangle has base 2+2+5=9 and height 3.5, area 15.75. Below are triangles of areas 2 and 5 and a2-by-2 rectangle of area 4. Total 26.75.", "expected_key": "B", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {}, "q_digest": "2355ab21569b1875c1f73add4c02b3e5", "key_digest": "44ac9fd4b942e7dce0481b9e401c5cdc", "fingerprint": "3ee68ccaf9666362cc9e3532c4f7c7ff"}, {"id": "a4ff981b-0a17-5b74-9989-4cdf4e3eb3a1", "status": "mathematically_verified", "solution": "Write y=a(x-1)(x-3). Then -4a=5, a=-5/4 and c=3a=-15/4; a+c=-5.", "expected_key": "D", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {}, "q_digest": "800d2bd3faf37b5dc322b859d80b1ea1", "key_digest": "6f1183ff917b6cbdc01f0be807d362a3", "fingerprint": "44b5c6f6659a6bd49ada24eb84c5f8bf"}, {"id": "a5d3bed4-5dea-5cb5-93fa-2393fe67c4ea", "status": "repair_and_verified", "solution": "The negative absolute value opens downward, with vertex (0, 3). Setting y = 0 gives |2x| = 3, so x = ±1.5.", "expected_key": "A", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {"image": "https://math.portal.ghoneem.com/exams/est-banks-2026/figures/aaf-001-1.png", "choices": [{"key": "A", "text": "V-shaped graph opening downward with vertex at (0, 3), crossing the x-axis at x = −1.5 and x = 1.5"}, {"key": "B", "text": "V-shaped graph opening downward with vertex at (−1.5, 0)"}, {"key": "C", "text": "V-shaped graph opening downward with vertex at (0, −3)"}, {"key": "D", "text": "V-shaped graph opening upward with vertex at (0, 1)"}]}, "q_digest": "8135c6ad31e6b230da505df2f62a5c8a", "key_digest": "9ce521f012d129869aad83ee6206b8d5", "fingerprint": "aa1b340f5be150b3534a3b47031131b8"}, {"id": "a683472f-c368-577d-b2b7-470be3abc0cf", "status": "repair_and_verified", "solution": "Counting the graph''s grid squares gives a fall of 7 units over a run of 8 units, so the slope is −7/8.", "expected_key": "B", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {"image": "https://math.portal.ghoneem.com/exams/est-banks-2026/figures/fa-034-1.png"}, "q_digest": "6a015d6fea8a4fc61bb9bb3dde5e6c7b", "key_digest": "16f4564fd6d66116f1d4a8e2c30505bc", "fingerprint": "6139f1de8260cb09c2ac1296fdf6714d"}, {"id": "a6870e82-1939-53cf-8088-18a358f89d0e", "status": "mathematically_verified", "solution": "x^2-5x+6=(x-2)(x-3); substitution at x=2 gives zero.", "expected_key": "A", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {}, "q_digest": "f675ebfd757c7fae68670a0cdd41b6b0", "key_digest": "046be963184de94ea454d483d66ab130", "fingerprint": "3be5e64fe2eea17c181c93c75305a6d9"}, {"id": "a6a7c3e1-f1c7-58c7-b016-0225acb4bd7c", "status": "mathematically_verified", "solution": "340*0.20*0.5=34.", "expected_key": "D", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {}, "q_digest": "1788422b5922f3386bbdd6ac2b1215a3", "key_digest": "c2813e61ec6e3ad7ec203522cb42dca6", "fingerprint": "2bd66be93b76292ff09aae637de0a98b"}, {"id": "a8337873-62ce-5c28-849f-52cce670253b", "status": "mathematically_verified", "solution": "To reverse a 20% discount, multiply 0.8 by 1.25. Increase relative to discounted price is 25%.", "expected_key": "C", "source_image_checked": true, "scope": "Original source crop visually checked; independent algebra, probability, units and diagram calculations. Existing source images retained.", "repair": {}, "q_digest": "8b2982b7eb4ffef19b1757ddb53d966d", "key_digest": "f77db6d66b26c0d1f99f29773e84ea51", "fingerprint": "c7dc1ceecbfb739f7d8d96b5bc203ef7"}]'::jsonb)
as t(id uuid,status text,solution text,expected_key text,source_image_checked boolean,scope text,repair jsonb,q_digest text,key_digest text,fingerprint text,old_stem text);
do $$ begin
if exists(select 1 from audit_log where action='questions.est_remaining_batch07.20260930') then raise exception 'Batch already applied'; end if;
if (select count(*) from est_review_batch t join questions q on q.id=t.id join question_keys k on k.question_id=q.id where q.track_id='est' and md5(to_jsonb(q)::text)=t.q_digest and md5(to_jsonb(k)::text)=t.key_digest and k.correct#>>'{}'=t.expected_key and nullif(q.assets->>'release_hold_reason','') is null)<>50 then raise exception 'Reviewed question version changed'; end if;
end $$;
create temporary table est_review_revision_before on commit drop as
select r.question_id,r.active,r.fingerprint=t.fingerprint was_ready
from revision_items r join est_review_batch t on t.id=r.question_id;
insert into audit_log(action,target_type,target_id,meta)
select 'questions.est_remaining_batch07.20260930','question',q.id::text,
jsonb_build_object('previous_stem',q.stem,'previous_choices',q.choices,'previous_assets',q.assets,'previous_explanation',k.explanation,'solution',t.solution,'scope',t.scope,'source_image_checked',t.source_image_checked,'status',t.status)
from est_review_batch t join questions q on q.id=t.id join question_keys k on k.question_id=q.id;
update questions q set
stem=coalesce(t.repair->>'stem',q.stem),
choices=coalesce(t.repair->'choices',q.choices),
assets=q.assets||jsonb_build_object('answer_review','2026-09-30-independent-current-stem-review','mathematical_review_scope',t.scope)||
case when t.repair ? 'image' then jsonb_build_object('image',t.repair->>'image') else '{}'::jsonb end
from est_review_batch t where q.id=t.id;
update question_keys k set explanation=t.repair->>'explanation'
from est_review_batch t where k.question_id=t.id and t.repair ? 'explanation';
update revision_items r set fingerprint=revision_question_fingerprint(q.stem,q.choices,q.assets,k.correct,k.explanation)
from questions q join question_keys k on k.question_id=q.id join est_review_revision_before b on b.question_id=q.id
where r.question_id=q.id and b.was_ready;
do $$ begin
if exists(select 1 from est_review_revision_before b join revision_items r using(question_id) where r.active is distinct from b.active) then raise exception 'Release status changed'; end if;
if (select count(*) from audit_log where action='questions.est_remaining_batch07.20260930')<>50 then raise exception 'Audit incomplete'; end if;
end $$;
commit;
